package org.tinytube.app;

/** The subscription list. Generated by tools/gen-channels.py -- do not hand-edit. */
final class Chans {
    private Chans() {}

    /** Flat id,name pairs: cheaper in dex than an array of objects. */
    static final String[] ALL = {};

    static int count() { return ALL.length / 2; }
    static String id(int i) { return ALL[i * 2]; }
    static String name(int i) { return ALL[i * 2 + 1]; }

    static String nameOf(String id) {
        for (int i = 0; i < ALL.length; i += 2) if (ALL[i].equals(id)) return ALL[i + 1];
        return "";
    }
}
